import 'dart:convert';

import 'package:flutter/services.dart';

import 'azkar_catalog.dart';

/// The bundled corpus. `assets/azkar/azkar.json` is generated by
/// `tool/import_azkar.py`; never edit it by hand.
abstract final class AzkarCorpus {
  static const asset = 'packages/academy_islamic/assets/azkar/azkar.json';

  /// «Крепость мусульманина» (Hisn al-Muslim), generated by
  /// `tool/import_hisn.py`; never edit by hand. Its source repository states
  /// no license: shipping it is the app owner's decision (CHANGELOG 0.5.0).
  static const hisnAsset = 'packages/academy_islamic/assets/azkar/hisn.json';

  /// Word-by-word glosses of the azkar and the Hisn duas, generated by
  /// `tool/import_words.py` from `tool/words_ru.tsv`; never edit by hand.
  static const wordsAsset = 'packages/academy_islamic/assets/azkar/words.json';

  /// Reads the corpus once, with «Крепость мусульманина»
  /// ([AzkarCatalog.chapters]) and the glosses of its words
  /// ([Zikr.wordGlosses]). An app may pass its own [hisn] document or [words]
  /// glosses: [hisn] replaces the bundled one, [words] are added to the
  /// bundled glosses and win on the same id.
  static Future<AzkarCatalog> load(
    AssetBundle bundle, {
    Map<String, dynamic>? hisn,
    Map<String, dynamic>? words,
  }) async {
    final [azkar, bundledHisn, glosses] = await Future.wait([
      bundle.loadString(asset),
      if (hisn == null) bundle.loadString(hisnAsset) else Future.value(''),
      bundle.loadString(wordsAsset),
    ]);
    return AzkarCatalog.fromJson(
      jsonDecode(azkar) as Map<String, dynamic>,
      hisn: hisn ?? jsonDecode(bundledHisn) as Map<String, dynamic>,
      words: {...jsonDecode(glosses) as Map<String, dynamic>, ...?words},
    );
  }
}
